from collections import defaultdict, Counter
def r2(x): return x.quantize(D('0.01'), rounding=ROUND_HALF_UP)
def dig(s): return re.sub(r'\D','',str(s)).zfill(14)
wb = openpyxl.load_workbook(sys.argv[1], data_only=True); ws = wb['Operações']
rows=[r for r in ws.iter_rows(min_row=6, values_only=True) if r[0] and str(r[0]).startswith('PC-')]
print("linhas", len(rows))
c = Counter(r[0] for r in rows); dups=[k for k,v in c.items() if v>1]; print("dups", dups)
for r in rows:
    if r[0] in dups: print(r)
tw = openpyxl.load_workbook(sys.argv[2], data_only=True)['Taxas vigentes']
contr={}; nome={}
for r in tw.iter_rows(min_row=5, values_only=True):
    if not r[1]: continue
    if r[11] and 'INATIVO' in str(r[11]): continue
    cn=dig(r[1]); v=r[9]
    if v is None or (isinstance(v,str) and v.strip().lower()=='padrão'): pp=D('1.5')
    else: pp=(D(str(v))*100)
    contr[cn]=pp; nome.setdefault(cn, r[0])
seen=set(); com=defaultdict(D); n=defaultdict(int); neg=[]; div=defaultdict(list); tot=D(0)
statuses=Counter(); obs=Counter(); spread_sum=D(0)
for r in rows:
    nop=r[0]
    if nop in seen: continue
    seen.add(nop)
    cn=dig(r[3]); sp=D(str(r[10])); vme=D(str(r[6])); ptax=D(str(r[8])); spp=D(str(r[11]))*100
    statuses[r[14]]+=1; obs[r[15]]+=1
    if cn not in contr: print("SEM CADASTRO", cn, r[4])
    cp=contr.get(cn)
    if sp<0:
        neg.append((nop,cn,r[4],sp, r2(sp - cp/100*vme*ptax), spp, cp, r[15], r[12])); continue
    p=r2(sp/2); com[cn]+=p; n[cn]+=1; tot+=p; spread_sum+=sp
    if cp is not None and abs(spp-cp)>=D('0.01'):
        div[cn].append((nop, spp, cp, r2((spp-cp)/100*vme*ptax), r2(sp*(spp-cp)/spp)))
print("unicas", len(seen), "incluidas", sum(n.values()), "comissao", tot, "spread incl", spread_sum)
for cn in sorted(com): print(cn, nome.get(cn), n[cn], com[cn], contr.get(cn))
print("NEG", len(neg), sum(x[3] for x in neg), sum(x[4] for x in neg))
for x in neg: print(x)
for cn,l in div.items():
    print("DIV", cn, nome.get(cn), len(l), sum(x[3] for x in l), sum(x[4] for x in l))
    for x in l: print("  ",x)
print(statuses, obs)
# near-tolerance check
for r in rows:
    cn=dig(r[3]); cp=contr.get(cn); spp=D(str(r[11]))*100
    if cp is not None and D('0.003')<abs(spp-cp)<D('0.1'): print("NEAR", r[0], cn, spp, cp)
